from hmac import compare_digest as compare_hash

def login():
    username = input('Python login: ')
    decryptedpasswd = pwd.getpwnam(username)[1]
    if decryptedpasswd:
        if decryptedpasswd == 'x' or decryptedpasswd == '*':
            raise ValueError('no support for shadow passwords')
        cleartext = getpass.getpass()
        return compare_hash(crypt.crypt(cleartext, decryptedpasswd), decryptedpasswd)
    else:
        return True

